namespace OneSpeech;

public static partial class Speech
{
    /// <summary>Enrolls or replaces a case-sensitive nonblank name in process memory only. Obtain speaker consent and comply with local biometric laws. Samples are downmixed to mono 16 kHz, nonempty, at most 60 seconds. Language selects English CAM++ by default or Chinese CAM++ for zh; model explicitly selects either catalog ID. Missing weights download on first use. Throws ArgumentException, typed audio/model/capability errors or IOException. ClearSpeakers releases enrollments and loaded speaker models. Never persists embeddings. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static void Enroll(string name, string path, string? language = null, string? model = null, CancellationToken cancellationToken = default) => Pipeline.SpeakerServices.Enroll(name, path, language, model, cancellationToken);
    /// <summary>Identifies the best enrolled name, or null for unknown, with raw cosine score (not a probability). Uses the calibrated inclusive threshold for the selected model; models have separate enrollment spaces. Empty registry returns negative infinity. Obtain consent and comply with local biometric laws; limits, defaults and errors follow Enroll. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static SpeakerMatch Identify(string path, string? language = null, string? model = null, CancellationToken cancellationToken = default) => Pipeline.SpeakerServices.Identify(path, language, model, cancellationToken);
    /// <summary>Scores two files without enrollment. Returns raw cosine in [-1,1], not a probability or an automatic verification decision. Obtain consent and comply with local biometric laws. Samples, defaults and errors follow Enroll; no embedding is persisted. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static double Verify(string firstPath, string secondPath, string? language = null, string? model = null, CancellationToken cancellationToken = default) => Pipeline.SpeakerServices.Verify(firstPath, secondPath, language, model, cancellationToken);
    /// <summary>Enrolls from a readable encoded-audio stream, borrowed and left open at its consumed position. Encoded input is temporarily spooled for decoding and deleted on completion or failure; embeddings are never persisted. Obtain consent and comply with local biometric laws. Limits/defaults/errors follow Enroll; cancellation throws OperationCanceledException. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static ValueTask EnrollAsync(string name, Stream stream, string? language = null, string? model = null, CancellationToken cancellationToken = default) => Pipeline.SpeakerServices.EnrollAsync(name, stream, language, model, cancellationToken);
    /// <summary>Identifies a borrowed readable encoded stream; leaves it open. Obtain consent and comply with local biometric laws. Temporary spooling, limits and errors follow EnrollAsync; scores and unknown handling follow Identify. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static ValueTask<SpeakerMatch> IdentifyAsync(Stream stream, string? language = null, string? model = null, CancellationToken cancellationToken = default) => Pipeline.SpeakerServices.IdentifyAsync(stream, language, model, cancellationToken);
    /// <summary>Scores two borrowed readable encoded streams, left open. Obtain consent and comply with local biometric laws. Temporary spooling, limits and errors follow EnrollAsync; score semantics follow Verify. No embedding is persisted. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static ValueTask<double> VerifyAsync(Stream first, Stream second, string? language = null, string? model = null, CancellationToken cancellationToken = default) => Pipeline.SpeakerServices.VerifyAsync(first, second, language, model, cancellationToken);
    /// <summary>Clears all process-wide enrollments and releases speaker models; nothing is persisted. Idempotent, waiting for active operations. Lock acquisition is cancellable; cancellation leaves state unchanged. Managed erasure is best effort, not protection against memory dumps. Obtain consent and comply with local biometric law before reenrollment. Companion IDs, conditional downloads and sizes are listed in docs/model-downloads.md.</summary>
    public static void ClearSpeakers(CancellationToken cancellationToken = default) => Pipeline.SpeakerServices.Clear(cancellationToken);
}
